def track(id,title,refs,objectives,hook,why,steps,compare,worked,transfer,sources):
 t=dict(id=id,title=title,refs=refs,objectives=objectives,hook=hook,why=why,steps=steps,compare=compare,worked=worked,transfer=transfer,sources=sources,questions=[]);tracks.append(t);return t
def q(t,skill,prompt,opts,clue,scope='core'):
 # Options are authored as [answer, explanation]; the UI shuffles their display.
 t['questions'].append(dict(id=t['id']+'-'+str(len(t['questions'])+1),skill=skill,prompt=prompt,options=[o[0] for o in opts],explanations=[o[1] for o in opts],correct=0,clue=clue,scope=scope))
