# Strengthen nearby alternatives: the distinction, rather than an unrelated option, does the work.
def revise(track_id,n,options):
 item=next(t for t in tracks if t['id']==track_id)['questions'][n-1]
 item['options']=[v[0] for v in options];item['explanations']=[v[1] for v in options]
