revise('access',3,[('NAC','Posture/admission policy restricts the device to remediation access.'),('A SIEM correlation rule that alerts on expired agents','Observes the issue but does not itself enforce admission.'),('A VPN gateway configured only to validate user credentials','User identity alone does not implement the required device-posture restriction.'),('An MDM inventory report listing outdated agents','Identifies device state but does not itself apply the stated network admission decision.')])
revise('access',5,[('MDM','Provides managed policy and wipe capabilities for tablets.'),('A SIEM collecting the tablets’ security events','Collects evidence but is not the primary device-management mechanism.'),('A NAC rule restricting corporate network entry','Can restrict entry but does not manage a lost device away from that network.'),('A WAF protecting the tablet application’s server','Protects server-side web input, not the tablet’s local configuration and wipe function.')])
revise('data',5,[('Credentials crossed the captured link without effective transport confidentiality','Readable credentials directly demonstrate exposure on that path.'),('An obsolete but functioning cipher was used on the captured link','Weak encryption is a concern, but readable cleartext alone does not establish a particular cipher.'),('The server stored its password database without salts','A packet capture does not establish the database storage format.'),('A certificate-authority private key was compromised','No evidence of issuer-key compromise is supplied.')])
revise('data',6,[('Journaling','Records transactions to support consistent crash recovery.'),('A checksum comparison alone','Can detect changed data but does not itself replay pending updates.'),('A scheduled full backup','Provides a recovery copy, but the described mechanism consults update records.'),('Whole-disk encryption','Protects confidentiality, not pending filesystem transaction consistency.')])
revise('data',7,[('Digital signature','Provides publisher-origin and integrity verification while content remains readable.'),('An unsigned checksum posted beside the file on the same untrusted mirror','Can reveal accidental differences but an attacker can replace both file and checksum.'),('Encryption with a key distributed to every customer','Shared-key encryption does not uniquely establish the publisher as signer.'),('A file-size comparison against the previous release','Matching size neither proves origin nor excludes modification.')])
revise('response',2,[('A custody record with identities, times and evidence-item details','Documents the specific handoff and custodians.'),('Only a cryptographic hash of the drive image','Supports integrity comparison but does not identify who held it.'),('Only a preservation notice for relevant data','Requires retention but does not document this transfer.'),('Only the search terms used during evidence review','Supports the review process, not possession history.')])
revise('response',3,[('Suspend the applicable deletion under legal hold','Directly preserves the records from routine destruction.'),('Calculate a hash while leaving the deletion job enabled','A digest cannot reconstruct deleted contents.'),('Record the mailbox administrator’s name in a custody form only','A custody record alone does not stop scheduled deletion.'),('Create a report listing matching messages without preserving them','A listing is not preservation of the actual responsive material.')])
revise('response',4,[('Its enabled host firewall log','The endpoint observes its own connections on the hotspot route.'),('The bypassed corporate gateway’s traffic log','The flow does not traverse that gateway.'),('The corporate wireless controller’s connection log alone','Can show departure from corporate Wi-Fi, but not necessarily the later outbound hotspot flows.'),('The corporate DNS resolver’s log when the hotspot uses another resolver','A resolver that is not queried cannot record those lookups.')])
revise('assets',4,[('Detecting hardware configuration changes','Component listings compared with a baseline reveal changes.'),('Verifying that the person logging in used two factors','Hardware inventory does not establish the authentication method.'),('Determining which public services an external scanner can reach','Local hardware inventory is not an external service-reachability test.'),('Proving all installed software is patched','A hardware snapshot does not by itself verify software patch state.')])
revise('decisions',4,[('Restrict the admin endpoint to the approved path and authorized users','Directly meets the reachability and access constraint.'),('Alert in the SIEM whenever the public admin page is requested','Detection does not prevent unauthenticated reachability.'),('Encrypt the public connection while leaving the admin endpoint unrestricted','Confidentiality of the path does not implement the requested access restriction.'),('Back up the admin server more frequently','Recovery readiness does not restrict current access.')])
revise('decisions',7,[('FIM — File Integrity Monitoring','Compares file state to detect unauthorized changes.'),('DLP — Data Loss Prevention','Targets inappropriate data movement or disclosure rather than any file change.'),('NAC — Network Access Control','Controls admission or posture, not specifically a protected file baseline.'),('A network intrusion sensor without host-file telemetry','Can observe network activity but lacks the stated local file comparison.')])

assert len(tracks)==8
ids=set();prompts=set()
for t in tracks:
 assert len(t['questions'])==10
 assert sum(q['scope']=='core' for q in t['questions'])==7
 for question in t['questions']:
  assert question['id'] not in ids and question['prompt'] not in prompts
  ids.add(question['id']);prompts.add(question['prompt'])
  assert len(set(question['options']))==4 and len(question['explanations'])==4
Path('js/targeted-data.js').write_text('/* Original targeted teaching and questions; no personal results are embedded. */\nwindow.TARGETED_TRACKS='+json.dumps(tracks,ensure_ascii=False,separators=(',',':'))+';\n')
print(f'{len(tracks)} tracks / {len(ids)} original questions')
